      SUBROUTINE MMTXCC     ROTATION MATRIX FROM MISALIGNMENT APPLIED TO TRANSPORT COORDINATES, C     DERIVED FROM TRANSFORMATION FOR THREE-SPACE COORDINATESCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM8K.CIN'CC     LOCAL VARIABLESCC----------------------------------------------------------------      RM(1,1) = 1.0 + RM(1,1)      RM(2,2) = 1.0 + RM(2,2)      RM(3,3) = 1.0 + RM(3,3)C      MM(1,1) = (RM(1,1) - RM(1,3)*RM(3,1)/RM(3,3))/RM(3,3)      MM(1,2) = (RM(1,2) - RM(1,3)*RM(3,2)/RM(3,3))/RM(3,3)      MM(1,3) = RM(1,3)/RM(3,3)      MM(2,1) = (RM(2,1) - RM(2,3)*RM(3,1)/RM(3,3))/RM(3,3)      MM(2,2) = (RM(2,2) - RM(2,3)*RM(3,2)/RM(3,3))/RM(3,3)      MM(2,3) = RM(2,3)/RM(3,3)C      RETURN      END